solution.wrap.awk:
# wrap.awk w=WIDTH : re-flow paragraphs to at most WIDTH columns (a longer word keeps a line to itself)
function flush(   i, ln) {
  if (n == 0) return
  if (printed) print ""
  ln = ""
  for (i = 1; i <= n; i++) {
    if (ln == "") ln = word[i]
    else if (length(ln) + 1 + length(word[i]) <= w) ln = ln " " word[i]
    else { print ln; ln = word[i] }
  }
  print ln
  printed = 1
  n = 0
}
NF == 0 { flush(); next }
{ for (i = 1; i <= NF; i++) word[++n] = $i }
END { flush() }

