import base64
import difflib
import gzip
import json
import os
import re
import shutil
import signal
import subprocess
import sys
import tempfile

EPOCH = 1700000000


def apply_tree(box, tree):
    later = []
    for path, ent in tree.items():
        full = os.path.join(box, path)
        t = ent.get("t", "f")
