# stats.awk : per endpoint: count, min, max, average
$2 ~ /^[0-9]+$/ {
  v = $2 + 0
  if (!($1 in c)) { names[++n] = $1; mn[$1] = v; mx[$1] = v }
  c[$1]++; s[$1] += v
  if (v < mn[$1]) mn[$1] = v
  if (v > mx[$1]) mx[$1] = v
}
END {
  for (i = 2; i <= n; i++) {
    x = names[i]
    for (j = i - 1; j >= 1 && names[j] > x; j--) names[j + 1] = names[j]
    names[j + 1] = x
  }
  for (i = 1; i <= n; i++) { k = names[i]; printf "%s %d %d %d %.1f\n", k, c[k], mn[k], mx[k], s[k] / c[k] }
}

